Section H.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PML.fp_ok fx -> PML.fp_ok fx'.
Hypothesis INITL : TPS2.iosb_init_later_spec L.
Hypothesis LOCL : PMS.locale_ctor_later_spec L.
Hypothesis OPNEW : PMS.opnew_spec L HI.
Hypothesis STRRSV : PMS.str_reserve_spec L HI.
Hypothesis VRSV : PMS.vec_reserve_spec L HI.
Hypothesis VPUSH : PMS.vec_push_spec L HI.

Ltac rc_wk T := apply (TK.samem_weaken _ _ _ _ T); let a := fresh "a" in let Ha := fresh "Ha" in intros a Ha;
  cbv beta delta [RCS.KE1 RCS.KE2 RCS.KE3 RCS.KE4 RCS.KE7] in Ha |- *; lia.
Ltac rc_ch T := eapply TK.samem_trans; [rc_wk T|].
Ltac rc_inframe := let av := fresh "av" in let Hav := fresh "Hav" in intros av Hav;
  cbv beta delta [RCS.nframe RCS.sframe RCS.cframe RCS.wframe RCS.pframe] in Hav;
  repeat (destruct Hav as [<-|Hav]; [cbn [fst]; lia|]); destruct Hav.

Lemma stk_of_fr : forall (LB : list (Z * Z)) sp SCR (foot : Z -> Prop) (M0 Mx : mem) d scr,
  L5C.stk (hl_sptop L) M0 sp SCR -> TK2.FR L LB sp SCR foot M0 Mx -> d mod 16 = 0 -> 0 <= d -> 0 <= scr -> d + scr <= SCR ->
  L5C.stk (hl_sptop L) Mx (sp - d) scr.
Proof.
  intros LB sp SCR foot M0 Mx d scr (S1 & S2 & S3 & S4 & S5) [_ F2] Hd Hd0 Hs Hds.
  split; [apply CK.al16; assumption|]. split; [lia|]. split; [lia|]. split; [exact S4|].
  intros i Hi. apply F2. lia.
Qed.

Lemma inv_step : forall (LB LBc : list (Z * Z)) crc VM sp SCR Rr (M0 Ma Mb : mem) (K : Z -> Prop),
  L5C.stk (hl_sptop L) M0 sp SCR -> 0 <= SCR -> sp <= Rr -> Rr + 592 <= hl_sptop L -> TK2.blocks_ok L LB ->
  hi_heap HI LBc crc Ma VM -> TK2.FR L LB sp SCR (fun a => Rr <= a < Rr + 592) M0 Ma -> PML.img_ro Ma -> L5.defined Ma Rr 592 ->
  TK.samem K Ma Mb -> mem_grows Ma Mb -> (forall a, ~ K a -> (sp - SCR <= a < sp) \/ (Rr <= a < Rr + 592)) ->
  hi_heap HI LBc crc Mb VM /\ TK2.FR L LB sp SCR (fun a => Rr <= a < Rr + 592) M0 Mb /\ PML.img_ro Mb /\ L5.defined Mb Rr 592.
Proof.
  intros LB LBc crc VM sp SCR Rr M0 Ma Mb K (S1 & S2 & S3 & S4 & S5) SCR0 OR1 OR2 BOK HH FR RO DR AG MG HK.
  assert (KK : forall a, ~ (sp - SCR <= a < sp) -> ~ (Rr <= a < Rr + 592) -> K a).
  { intros a N1 N2. destruct (classic (K a)) as [Y|N]; [exact Y|]. exfalso. destruct (HK a N) as [X|X]; [exact (N1 X) | exact (N2 X)]. }
  split; [|split; [|split]].
  - apply (TK2.heap_pure_write L HI HIok LAY _ _ Ma Mb _ K HH ltac:(lia) AG MG). intros a Ha NK. left. destruct (HK a NK) as [X|X]; lia.
  - exact (TK2.FR_grows L LAY LB sp SCR _ M0 Ma Mb K FR AG MG BOK ltac:(lia) ltac:(lia) HK).
  - unfold PML.img_ro in *. apply (TK.img_clear_samem K Ma Mb _ _ AG); [lia | unfold PML.IMG_RO_HI; lia | | exact RO].
    intros i Hi. unfold PML.IMG_RO_HI in Hi. apply KK; lia.
  - exact (L5.defined_grows _ _ _ _ MG DR).
Qed.

Lemma inv_hstep : forall (LB LBk : list (Z * Z)) sp SCR Rr spc scr (W : list L5.range) (M0 Ma Mb : mem),
  L5C.stk (hl_sptop L) M0 sp SCR -> sp <= Rr -> Rr + 592 <= hl_sptop L -> TK2.blocks_ok L LB -> incl LB LBk ->
  TK2.FR L LB sp SCR (fun a => Rr <= a < Rr + 592) M0 Ma -> PML.img_ro Ma -> L5.defined Ma Rr 592 ->
  L5C.hpres L LBk spc scr W Ma Mb -> sp - SCR <= spc - scr -> spc <= sp -> 0 <= scr ->
  (forall w a, In w W -> L5.in_rng w a -> Rr <= a < Rr + 592) ->
  TK2.FR L LB sp SCR (fun a => Rr <= a < Rr + 592) M0 Mb /\ PML.img_ro Mb /\ L5.defined Mb Rr 592.
Proof.
  intros LB LBk sp SCR Rr spc scr W M0 Ma Mb (S1 & S2 & S3 & S4 & S5) OR1 OR2 BOK INC FR RO DR HP H1 H2 H3 HW.
  pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI. pose proof (PmLayout.ly_errno L LAY) as ERR.
  split; [|split].
  - apply (TK2.FR_hpres L LAY LB sp SCR _ M0 Ma Mb LBk spc scr W FR HP BOK INC); try lia.
    intros w a Hw Hin. right. exact (HW w a Hw Hin).
  - unfold PML.img_ro, L5.img_clear in *. intros i Hi. rewrite (L5C.hpres_kept _ _ _ _ _ _ _ i HP); [exact (RO i Hi)|].
    unfold PML.IMG_RO_HI in Hi. split; [lia|].
    split; [right; right; rewrite ILO, IHI; split; [lia | intros X; apply (PmLayout.ly_static L LAY) in X; lia]|].
    split; [unfold in_errno; rewrite ERR; lia|]. intros w Hw Hin. pose proof (HW w i Hw Hin). lia.
  - intros i Hi. apply (L5C.hpres_cdef _ _ _ _ _ _ _ (Rr + i) HP); [lia | right; left; split; lia | unfold in_errno; rewrite ERR; lia | apply DR; exact Hi].
Qed.

Lemma parser_init : forall (K : Z -> Prop) (M M' : mem) P o s b p, TK.samem K M M' -> 0 <= P < 2 ^ 60 -> (forall i, P <= i < P + 224 -> K i) ->
  s = P + 224 -> o = P + 248 -> RCS.pcells M P -> PML.str_at M' s (PML.SLong 264 p []) -> L5.u64_at RSEGS M' o b ->
  L5.u64_at RSEGS M' (o + 8) (b + 1) -> L5.u64_at RSEGS M' (o + 16) (b + 66) -> L5.bytes_at RSEGS M' b [0] -> L5.defined M' P 272 ->
  PML.parser_at M' P (PMS.ps_init b p).
Proof.
  intros K M M' P o s b p AG HP HK -> -> (P0 & P8 & P12 & P13 & P14 & P16 & P17 & P18 & P24 & P96 & P128 & P144 & PZ168 & P208 & P212 & P216 & _) STR V0 V8 V16 VB DF.
  replace (P + 248 + 8) with (P + 256) in V8 by lia. replace (P + 248 + 16) with (P + 264) in V16 by lia.
  assert (X64 : forall o v, 0 <= o -> o + 8 <= 224 -> L5.u64_at RSEGS M (P + o) v -> L5.u64_at RSEGS M' (P + o) v).
  { intros o v H1 H2 H. apply (TK.u64_samem K M M' _ _ AG); [lia | intros i Hi; apply HK; lia | exact H]. }
  assert (X32 : forall o v, 0 <= o -> o + 4 <= 224 -> L5.u32_at RSEGS M (P + o) v -> L5.u32_at RSEGS M' (P + o) v).
  { intros o v H1 H2 H. apply (TK.u32_samem K M M' _ _ AG); [lia | intros i Hi; apply HK; lia | exact H]. }
  assert (X8 : forall o v, 0 <= o -> o + 1 <= 224 -> L5.u8_at RSEGS M (P + o) v -> L5.u8_at RSEGS M' (P + o) v).
  { intros o v H1 H2 H. apply (TK.u8_samem K M M' _ _ AG); [lia | apply HK; lia | exact H]. }
  destruct (u16_256 M (P + 14) ltac:(lia) ltac:(lia) P14) as (A14 & A15). replace (P + 14 + 1) with (P + 15) in A15 by lia.
  destruct (u32_1001 M (P + 208) ltac:(lia) ltac:(lia) P208) as (A208 & A209 & A210 & A211).
  replace (P + 208 + 1) with (P + 209) in A209 by lia. replace (P + 208 + 2) with (P + 210) in A210 by lia.
  replace (P + 208 + 3) with (P + 211) in A211 by lia.
  destruct (u16_0 M (P + 212) ltac:(lia) ltac:(lia) P212) as (A212 & A213). replace (P + 212 + 1) with (P + 213) in A213 by lia.
  pose proof (P24 0 ltac:(lia)) as L24. pose proof (P24 3 ltac:(lia)) as L48. pose proof (P24 6 ltac:(lia)) as L72.
